import { ValidationResult } from './types';
import { get } from 'openiban_http';

export interface OpenibanOptions {
  getBIC?: boolean;
  validateBankCode?: boolean;
}

const defaultOptions = {
  getBIC: true,
  validateBankCode: true
}

export function validate(iban: string, opts: OpenibanOptions = defaultOptions): Promise<ValidationResult> {
  const optionsString =
    `?getBIC=${opts.getBIC || 'false'}&validateBankCode=${opts.validateBankCode || 'false'}`;
  const url = '/validate/' + iban + optionsString;

  return get(url)
    .then((response) => {
      return response as ValidationResult;
    })
    .catch((err) => {
      return err;
    });
}

export interface OpenibanResponse {
  valid: boolean;
}

export interface CheckResults {
  /**
   * If a validateBankCode was set to true, this is the check result.
   */
  bankCode: boolean;
}
export interface BankData {
  bankCode: string;
  bic: string;
  city: string;
  name: string;
  zip: string;
}
export interface ValidationResult {
  /**
   * True when iban is considered as technically valid.
   */
  valid: boolean;
  /**
   * Messages returned by the openiban.com validation webservice.
   */
  messages: string[];
  /**
   * The original iban that this validation result refers to.
   */
  iban: string;
  /**
   * Contains details about the iban's issuing bank (if available).
   */
  bankData?: BankData;

  checkResults?: CheckResults;
}

import { OpenibanResponse } from './types';

const https = require('https');

export function get(url: string): Promise<OpenibanResponse> {
  const options = {
    host: 'openiban.com',
    port: 443,
    path: url,
    method: 'get',
    headers: { 'Accept': '*/*' }
  };

  return new Promise((resolve, reject) => {
    https.get(options, (res: any) => {
      res.on('data', (d: String | Buffer) => {
        resolve(JSON.parse(d.toString()));
      });
    }).on('error', (err: Error) => {
      reject(err);
    });
  });
}
